// ============================================================================
// Klong Phai Farm CRM — front-end logic.
//
// There is no separate backend server for this app. Every read/write below
// goes straight from the browser to Supabase, authenticated as whoever is
// logged in. What that person is allowed to see or change is enforced by the
// Row Level Security policies in sql/schema.sql, on the database side — not
// by anything in this file. Treat this file as UI convenience only, never as
// the security boundary.
// ============================================================================

const sb = window.supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

const STAGE_LABEL = {
  lead: "Lead", qualified: "Qualified", proposal: "Proposal",
  won: "Won", at_risk: "At risk", dormant: "Dormant", lost: "Lost",
};

// Klong Phai Farm logo, embedded so quotation PDFs don't need to fetch an
// external image file (and so the PDF still generates if the site is ever
// viewed offline/cached). Resized down from the original artwork — a PDF
// header logo doesn't need print-poster resolution.
const LOGO_BASE64 = "data:image/png;base64,";

let myProfile = null;     // { id, full_name, role }
let editingId = null;     // client id currently open in the modal, or null = "new"
let directorView = "mine"; // director only: "mine" (own pipeline) or "leads" (team leads feed)
let adminView = "all";     // admin only: "all" (full record list) or "summary" (per-rep achievement)

// ---------------------------------------------------------------- elements
const loginScreen  = document.getElementById("login-screen");
const appScreen    = document.getElementById("app-screen");
const loginForm    = document.getElementById("login-form");
const loginError   = document.getElementById("login-error");
const mfaBlock     = document.getElementById("mfa-block");
const directorTabs = document.getElementById("director-tabs");
const tabMineBtn   = document.getElementById("tab-mine");
const tabLeadsBtn  = document.getElementById("tab-leads");
const adminTabs    = document.getElementById("admin-tabs");
const tabAllBtn    = document.getElementById("tab-all");
const tabSummaryBtn = document.getElementById("tab-summary");
const tabProductsBtn = document.getElementById("tab-products");
const clientsTable = document.getElementById("clients-table");
const summaryTable = document.getElementById("summary-table");
const productsSection = document.getElementById("products-section");
const pipelineStats = document.getElementById("pipeline-stats");
const generateQuoteBtn = document.getElementById("generate-quote-btn");

let editingRecord = null;   // the full client row currently open in the edit modal, or null
let productCatalog = [];    // cached product list, reloaded each time the quote modal opens

init();

async function init() {
  const { data: { session } } = await sb.auth.getSession();
  if (session) {
    await onSignedIn();
  } else {
    showLogin();
  }
}

// --------------------------------------------------------------- auth flow
loginForm.addEventListener("submit", async (e) => {
  e.preventDefault();
  loginError.textContent = "";
  const email = document.getElementById("email").value.trim();
  const password = document.getElementById("password").value;

  const { error } = await sb.auth.signInWithPassword({ email, password });
  if (error) {
    loginError.textContent = error.message;
    return;
  }

  // If this account has an authenticator app enrolled, Supabase will report
  // that the session is stuck at "aal1" and needs a TOTP code to reach
  // "aal2" before it's fully authenticated.
  const { data: level } = await sb.auth.mfa.getAuthenticatorAssuranceLevel();
  if (level.currentLevel === "aal1" && level.nextLevel === "aal2") {
    const { data: factors } = await sb.auth.mfa.listFactors();
    const totp = factors.totp[0];
    mfaBlock.classList.remove("hidden");
    const code = prompt("Enter your 6-digit authenticator code:");
    const { data: challenge, error: chErr } = await sb.auth.mfa.challenge({ factorId: totp.id });
    if (chErr) { loginError.textContent = chErr.message; return; }
    const { error: verErr } = await sb.auth.mfa.verify({
      factorId: totp.id, challengeId: challenge.id, code,
    });
    if (verErr) { loginError.textContent = "Wrong code — try again."; return; }
  }

  await onSignedIn();
});

document.getElementById("sign-out-btn").addEventListener("click", async () => {
  await sb.auth.signOut();
  myProfile = null;
  showLogin();
});

function showLogin() {
  appScreen.classList.add("hidden");
  loginScreen.classList.remove("hidden");
}

async function onSignedIn() {
  const { data: { user } } = await sb.auth.getUser();
  const { data: profile, error } = await sb
    .from("profiles")
    .select("id, full_name, role")
    .eq("id", user.id)
    .single();

  if (error || !profile) {
    loginError.textContent = "Signed in, but no profile row exists for this account yet — ask your admin.";
    await sb.auth.signOut();
    return;
  }

  myProfile = profile;
  loginScreen.classList.add("hidden");
  appScreen.classList.remove("hidden");
  document.getElementById("who-name").textContent = myProfile.full_name;
  document.getElementById("who-role").textContent = myProfile.role;

  setupForRole();
  await loadClients();
}

// ------------------------------------------------------ role-specific setup
function setupForRole() {
  const title = document.getElementById("list-title");
  const note  = document.getElementById("role-note");
  const newBtn = document.getElementById("new-client-btn");
  const assignedWrap = document.getElementById("assigned-to-wrap");

  // Reset director/admin-only UI; re-enabled below only for that role.
  directorTabs.classList.add("hidden");
  adminTabs.classList.add("hidden");
  clientsTable.classList.remove("hidden");
  summaryTable.classList.add("hidden");
  productsSection.classList.add("hidden");
  pipelineStats.classList.add("hidden");
  newBtn.classList.remove("hidden");

  if (myProfile.role === "admin") {
    // Admin gets two views: the full record list (as before), and a
    // per-sales-rep achievement summary — counts by stage plus won/open
    // pipeline value. Admin-only, same as the CEO-level visibility already
    // required for this role.
    adminTabs.classList.remove("hidden");
    adminView = "all";
    tabAllBtn.classList.add("active");
    tabSummaryBtn.classList.remove("active");
    tabProductsBtn.classList.remove("active");
    title.textContent = "All clients & deals";
    note.textContent = "You see every record. Deal values and assignment are visible and editable.";
    assignedWrap.classList.remove("hidden");
    populateAssignedToDropdown();
  } else if (myProfile.role === "director") {
    // Director gets two views: their own personal pipeline (targets/visits,
    // just like a sales rep), and a read-only feed of new leads across the
    // whole team. Default to their own pipeline.
    directorTabs.classList.remove("hidden");
    directorView = "mine";
    tabMineBtn.classList.add("active");
    tabLeadsBtn.classList.remove("active");
    updateDirectorHeader();
  } else {
    title.textContent = "Your pipeline";
    note.textContent = "You only see clients assigned to you.";
  }
}

function updateDirectorHeader() {
  const title = document.getElementById("list-title");
  const note  = document.getElementById("role-note");
  const newBtn = document.getElementById("new-client-btn");

  if (directorView === "mine") {
    title.textContent = "My pipeline";
    note.textContent = "Your own clients and deals, just like a sales rep — only you can see this.";
    newBtn.classList.remove("hidden");
  } else {
    title.textContent = "Team leads";
    note.textContent = "New leads across the whole team — read-only. Not deal values, not other reps' pipelines.";
    newBtn.classList.add("hidden"); // read-only feed, nothing to create here
  }
}

tabMineBtn.addEventListener("click", () => switchDirectorView("mine"));
tabLeadsBtn.addEventListener("click", () => switchDirectorView("leads"));

async function switchDirectorView(view) {
  directorView = view;
  tabMineBtn.classList.toggle("active", view === "mine");
  tabLeadsBtn.classList.toggle("active", view === "leads");
  updateDirectorHeader();
  await loadClients();
}

tabAllBtn.addEventListener("click", () => switchAdminView("all"));
tabSummaryBtn.addEventListener("click", () => switchAdminView("summary"));
tabProductsBtn.addEventListener("click", () => switchAdminView("products"));

async function switchAdminView(view) {
  adminView = view;
  tabAllBtn.classList.toggle("active", view === "all");
  tabSummaryBtn.classList.toggle("active", view === "summary");
  tabProductsBtn.classList.toggle("active", view === "products");
  clientsTable.classList.toggle("hidden", view !== "all");
  summaryTable.classList.toggle("hidden", view !== "summary");
  productsSection.classList.toggle("hidden", view !== "products");
  pipelineStats.classList.add("hidden"); // never shown on any admin view
  document.getElementById("new-client-btn").classList.toggle("hidden", view !== "all");
  document.getElementById("list-title").textContent =
    view === "all" ? "All clients & deals" : view === "summary" ? "Team summary" : "Products";
  document.getElementById("role-note").textContent = view === "all"
    ? "You see every record. Deal values and assignment are visible and editable."
    : view === "summary"
    ? "Totals per sales rep — stage breakdown, won value, and open pipeline value. Only you can see this."
    : "The price list your reps pick from when building a quotation. Deactivating a product hides it from the picker without deleting past quotations that used it.";

  if (view === "summary") {
    await loadSummary();
  } else if (view === "products") {
    await loadProductsAdmin();
  } else {
    await loadClients();
  }
}

// --------------------------------------------------------- personal stats
// Win rate is deliberately based only on "won" vs "at_risk" — the accounts
// actually being tracked month to month — not leads/qualified/proposal/
// dormant/lost, which aren't part of "did they order this month or not".
function winRate(won, atRisk) {
  const tracked = won + atRisk;
  return tracked > 0 ? Math.round((won / tracked) * 100) : null;
}

function renderPipelineStats(rows) {
  const won = rows.filter(c => c.stage === "won").length;
  const atRisk = rows.filter(c => c.stage === "at_risk").length;
  const atRiskValue = rows
    .filter(c => c.stage === "at_risk")
    .reduce((sum, c) => sum + (Number(c.deal_value) || 0), 0);
  const rate = winRate(won, atRisk);

  const rateClass = rate === null ? "" : rate >= 50 ? "win-rate-good" : "win-rate-bad";
  const rateText = rate === null ? "—" : `${rate}%`;

  pipelineStats.innerHTML = `
    <span class="stat"><strong>${won}</strong>won this month</span>
    <span class="stat"><strong>${atRisk}</strong>at risk (haven't ordered yet)</span>
    ${atRisk > 0 ? `<span class="stat"><strong>${atRiskValue.toLocaleString()} ฿</strong>sitting at risk</span>` : ""}
    <span class="stat ${rateClass}"><strong>${rateText}</strong>win rate</span>
  `;
}

// ------------------------------------------------------------ team summary
async function loadSummary() {
  // Reuses the same "admin full access" RLS policy that already lets admin
  // read every clients/profiles row — no new database permissions needed.
  const [{ data: clients, error: cErr }, { data: profiles, error: pErr }] = await Promise.all([
    sb.from("clients").select("assigned_to, stage, deal_value"),
    sb.from("profiles").select("id, full_name, role").order("full_name"),
  ]);

  const head = document.getElementById("summary-head");
  const body = document.getElementById("summary-body");
  const err = cErr || pErr;

  if (err) {
    body.innerHTML = `<tr><td colspan="10">Couldn't load summary: ${err.message}</td></tr>`;
    return;
  }

  const OPEN_STAGES = ["lead", "qualified", "proposal", "at_risk", "dormant"];

  const byRep = {};
  (profiles || []).forEach(p => {
    if (p.role === "admin") return; // admin has no personal pipeline to summarize
    byRep[p.id] = {
      name: p.full_name, role: p.role,
      lead: 0, qualified: 0, proposal: 0, won: 0, at_risk: 0, dormant: 0, lost: 0,
      wonValue: 0, openValue: 0, atRiskValue: 0,
    };
  });

  (clients || []).forEach(c => {
    const rep = byRep[c.assigned_to];
    if (!rep) return; // unassigned row, or assigned to an admin — not shown per-rep
    rep[c.stage] = (rep[c.stage] || 0) + 1;
    const value = Number(c.deal_value) || 0;
    if (c.stage === "won") rep.wonValue += value;
    else if (OPEN_STAGES.includes(c.stage)) rep.openValue += value;
    if (c.stage === "at_risk") rep.atRiskValue += value;
  });

  head.innerHTML = `<tr>
      <th>Sales rep</th><th>Leads</th><th>Qualified</th><th>Proposal</th>
      <th>Won</th><th>At risk</th><th>Dormant</th><th>Lost</th>
      <th>Win rate</th>
      <th>Won value</th><th>At risk value</th><th>Open pipeline value</th>
    </tr>`;

  const rows = Object.values(byRep);

  if (!rows.length) {
    body.innerHTML = `<tr><td colspan="11">No sales reps or director yet.</td></tr>`;
    return;
  }

  body.innerHTML = rows.map(r => {
    const rate = winRate(r.won, r.at_risk);
    return `
    <tr>
      <td>${escapeHtml(r.name)}<br><small style="color:var(--muted)">${r.role}</small></td>
      <td>${r.lead}</td><td>${r.qualified}</td><td>${r.proposal}</td>
      <td>${r.won}</td><td>${r.at_risk}</td><td>${r.dormant}</td><td>${r.lost}</td>
      <td>${rate === null ? "—" : rate + "%"}</td>
      <td>${r.wonValue.toLocaleString()} ฿</td>
      <td>${r.atRiskValue.toLocaleString()} ฿</td>
      <td>${r.openValue.toLocaleString()} ฿</td>
    </tr>
  `;
  }).join("");

  const totals = rows.reduce((acc, r) => {
    ["lead", "qualified", "proposal", "won", "at_risk", "dormant", "lost", "wonValue", "openValue", "atRiskValue"]
      .forEach(k => { acc[k] = (acc[k] || 0) + r[k]; });
    return acc;
  }, {});
  const totalRate = winRate(totals.won, totals.at_risk);

  body.innerHTML += `
    <tr class="totals-row">
      <td>Total</td>
      <td>${totals.lead}</td><td>${totals.qualified}</td><td>${totals.proposal}</td>
      <td>${totals.won}</td><td>${totals.at_risk}</td><td>${totals.dormant}</td><td>${totals.lost}</td>
      <td>${totalRate === null ? "—" : totalRate + "%"}</td>
      <td>${totals.wonValue.toLocaleString()} ฿</td>
      <td>${totals.atRiskValue.toLocaleString()} ฿</td>
      <td>${totals.openValue.toLocaleString()} ฿</td>
    </tr>`;
}

// -------------------------------------------------------------- products
async function loadProductsAdmin() {
  const { data, error } = await sb.from("products").select("*").order("name");
  const body = document.getElementById("products-body");
  if (error) {
    body.innerHTML = `<tr><td colspan="5">Couldn't load products: ${error.message}</td></tr>`;
    return;
  }
  body.innerHTML = (data || []).map(p => `
    <tr>
      <td>${escapeHtml(p.name)}</td>
      <td>${escapeHtml(p.unit || "—")}</td>
      <td>${Number(p.unit_price).toLocaleString()} ฿</td>
      <td>${p.active ? '<span class="badge badge-won">Active</span>' : '<span class="badge badge-dormant">Inactive</span>'}</td>
      <td><button type="button" class="btn-link toggle-product-btn" data-id="${p.id}" data-active="${p.active}">${p.active ? "Deactivate" : "Reactivate"}</button></td>
    </tr>
  `).join("") || `<tr><td colspan="5">No products yet — add your first one above.</td></tr>`;

  body.querySelectorAll(".toggle-product-btn").forEach(btn => {
    btn.addEventListener("click", async () => {
      const nowActive = btn.dataset.active === "true";
      await sb.from("products").update({ active: !nowActive }).eq("id", btn.dataset.id);
      await loadProductsAdmin();
    });
  });
}

document.getElementById("product-form").addEventListener("submit", async (e) => {
  e.preventDefault();
  const name = document.getElementById("p-name").value.trim();
  const unit = document.getElementById("p-unit").value.trim() || null;
  const price = document.getElementById("p-price").value;
  if (!name || price === "") return;

  const { error } = await sb.from("products").insert({ name, unit, unit_price: price });
  if (error) {
    alert("Couldn't add product: " + error.message);
    return;
  }
  document.getElementById("product-form").reset();
  await loadProductsAdmin();
});

// Loads the active product list fresh each time the quote builder opens, so
// a price change by admin is picked up immediately rather than from a stale
// cache.
async function loadProductCatalog() {
  const { data, error } = await sb.from("products").select("*").eq("active", true).order("name");
  productCatalog = error ? [] : (data || []);
  return productCatalog;
}

async function populateAssignedToDropdown() {
  const { data, error } = await sb.from("profiles").select("id, full_name, role").order("full_name");
  if (error) return;
  const sel = document.getElementById("f-assigned-to");
  sel.innerHTML = data.map(p => `<option value="${p.id}">${p.full_name} (${p.role})</option>`).join("");
}

// -------------------------------------------------------------- list/table
async function loadClients() {
  if (myProfile.role === "admin" && adminView === "summary") {
    await loadSummary();
    return;
  }

  const isDirector = myProfile.role === "director";
  const onTeamLeadsTab = isDirector && directorView === "leads";

  // Director "My pipeline" queries the real clients table filtered to their
  // own rows client-side (RLS on the server already permits this — see
  // "clients: director reads/inserts/updates own" in schema.sql). Director
  // "Team leads" uses the column-limited, org-wide director_leads view, same
  // as before. Everyone else is unchanged.
  let query;
  if (onTeamLeadsTab) {
    query = sb.from("director_leads").select("*");
  } else if (isDirector) {
    query = sb.from("clients").select("*").eq("assigned_to", myProfile.id);
  } else {
    query = sb.from("clients").select("*");
  }

  const { data, error } = await query.order("created_at", { ascending: false });

  const head = document.getElementById("table-head");
  const body = document.getElementById("table-body");

  if (error) {
    body.innerHTML = `<tr><td colspan="6">Couldn't load records: ${error.message}</td></tr>`;
    return;
  }

  const showValue = myProfile.role === "admin" || myProfile.role === "sales" || (isDirector && !onTeamLeadsTab);
  const showAssigned = myProfile.role === "admin";
  const editable = !onTeamLeadsTab; // admin, sales, and director's own pipeline are all editable

  // Personal "how am I doing" line for sales reps and the director's own
  // pipeline (not the admin views — they get the same numbers per rep in
  // Team summary — and not the director's org-wide Team leads feed, which
  // isn't a personal pipeline).
  const showPersonalStats = myProfile.role === "sales" || (isDirector && !onTeamLeadsTab);
  if (showPersonalStats) {
    renderPipelineStats(data || []);
    pipelineStats.classList.remove("hidden");
  } else {
    pipelineStats.classList.add("hidden");
  }

  head.innerHTML = `<tr>
      <th>Client</th><th>Segment</th><th>Stage</th>
      ${showValue ? "<th>Deal value</th>" : ""}
      <th>Next action</th>
      ${showAssigned ? "<th>Assigned to</th>" : ""}
    </tr>`;

  body.innerHTML = (data || []).map(c => `
    <tr class="clickable-row" data-id="${c.id}" data-editable="${editable}">
      <td>${escapeHtml(c.name)}${c.contact_name ? `<br><small>${escapeHtml(c.contact_name)}</small>` : ""}</td>
      <td>${escapeHtml(c.segment || "")}</td>
      <td><span class="badge badge-${c.stage}">${STAGE_LABEL[c.stage] || c.stage}</span></td>
      ${showValue ? `<td>${c.deal_value ? Number(c.deal_value).toLocaleString() + " ฿" : "—"}</td>` : ""}
      <td>${escapeHtml(c.next_action || "—")}${c.next_action_date ? `<br><small>${c.next_action_date}</small>` : ""}</td>
      ${showAssigned ? `<td>${c.assigned_to || "—"}</td>` : ""}
    </tr>
  `).join("") || `<tr><td colspan="6">Nothing here yet.</td></tr>`;

  body.querySelectorAll("tr.clickable-row").forEach(row => {
    if (row.dataset.editable === "true") {
      row.addEventListener("click", () => openEditModal(row.dataset.id, data));
    }
  });
}

function escapeHtml(str) {
  const d = document.createElement("div");
  d.textContent = str ?? "";
  return d.innerHTML;
}

// -------------------------------------------------------------- edit modal
const modal = document.getElementById("edit-modal");
const editForm = document.getElementById("edit-form");

document.getElementById("new-client-btn").addEventListener("click", () => openEditModal(null, []));
document.getElementById("cancel-edit-btn").addEventListener("click", closeModal);

function openEditModal(id, currentRows) {
  editingId = id;
  const record = id ? currentRows.find(r => r.id === id) : null;
  editingRecord = record;
  generateQuoteBtn.classList.toggle("hidden", !record);

  document.getElementById("modal-title").textContent = id ? "Edit client" : "New client";
  document.getElementById("f-name").value = record?.name || "";
  document.getElementById("f-contact").value = record?.contact_name || "";
  document.getElementById("f-phone").value = record?.phone || "";
  document.getElementById("f-email").value = record?.email || "";
  document.getElementById("f-segment").value = record?.segment || "Restaurant";
  document.getElementById("f-stage").value = record?.stage || "lead";
  document.getElementById("f-value").value = record?.deal_value ?? "";
  document.getElementById("f-next-date").value = record?.next_action_date || "";
  document.getElementById("f-next-action").value = record?.next_action || "";
  document.getElementById("f-notes").value = record?.notes || "";
  if (myProfile.role === "admin" && record?.assigned_to) {
    document.getElementById("f-assigned-to").value = record.assigned_to;
  }

  modal.classList.remove("hidden");
}

function closeModal() {
  modal.classList.add("hidden");
  editingId = null;
  editingRecord = null;
}

editForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  const payload = {
    name: document.getElementById("f-name").value.trim(),
    contact_name: document.getElementById("f-contact").value.trim() || null,
    phone: document.getElementById("f-phone").value.trim() || null,
    email: document.getElementById("f-email").value.trim() || null,
    segment: document.getElementById("f-segment").value,
    stage: document.getElementById("f-stage").value,
    deal_value: document.getElementById("f-value").value || null,
    next_action_date: document.getElementById("f-next-date").value || null,
    next_action: document.getElementById("f-next-action").value.trim() || null,
    notes: document.getElementById("f-notes").value.trim() || null,
  };

  if (myProfile.role === "admin") {
    payload.assigned_to = document.getElementById("f-assigned-to").value;
  } else if (!editingId) {
    payload.assigned_to = myProfile.id; // sales reps always own what they create
  }

  const query = editingId
    ? sb.from("clients").update(payload).eq("id", editingId)
    : sb.from("clients").insert(payload);

  const { error } = await query;
  if (error) {
    alert("Couldn't save: " + error.message);
    return;
  }

  closeModal();
  await loadClients();
});

// ============================================================================
// Quotation builder — pick products from the catalog, set quantities and a
// valid-until date, generate a branded PDF in the browser, save a record of
// what was quoted, and (if EmailJS is configured in config.js) email Clément
// a notification. No backend involved anywhere in this flow — the PDF is
// built client-side and the "send" is a service designed to be called
// straight from a browser.
// ============================================================================
const quoteModal = document.getElementById("quote-modal");
const quoteForm = document.getElementById("quote-form");
const quoteLinesBody = document.getElementById("quote-lines-body");
const quoteError = document.getElementById("quote-error");
let currentQuoteClient = null;
let quoteLineSeq = 0;

if (typeof emailjs !== "undefined" && EMAILJS_PUBLIC_KEY) {
  emailjs.init({ publicKey: EMAILJS_PUBLIC_KEY });
}

generateQuoteBtn.addEventListener("click", () => {
  const client = editingRecord;
  closeModal();
  if (client) openQuoteModal(client);
});

document.getElementById("cancel-quote-btn").addEventListener("click", closeQuoteModal);

function closeQuoteModal() {
  quoteModal.classList.add("hidden");
  currentQuoteClient = null;
}

async function openQuoteModal(client) {
  currentQuoteClient = client;
  quoteError.textContent = "";
  document.getElementById("quote-client-name").textContent = client.name;
  document.getElementById("q-entity").value = "Prosun Farm";
  document.getElementById("q-cust-name").value = client.contact_name || client.name || "";
  document.getElementById("q-cust-company").value = client.name || "";
  document.getElementById("q-cust-address").value = "";
  document.getElementById("q-cust-cityzip").value = client.delivery_area || "";
  document.getElementById("q-cust-phone").value = client.phone || "";
  document.getElementById("q-tax-rate").value = 7;
  document.getElementById("q-other").value = 0;

  const inTwoWeeks = new Date();
  inTwoWeeks.setDate(inTwoWeeks.getDate() + 14);
  document.getElementById("q-valid-until").value = inTwoWeeks.toISOString().slice(0, 10);

  await loadProductCatalog();
  quoteLinesBody.innerHTML = "";
  quoteLineSeq = 0;
  addQuoteLineRow();

  quoteModal.classList.remove("hidden");
}

document.getElementById("add-quote-line-btn").addEventListener("click", () => addQuoteLineRow());

function addQuoteLineRow() {
  const rowId = `qline-${quoteLineSeq++}`;
  const options = productCatalog.map(p =>
    `<option value="${p.id}" data-price="${p.unit_price}">${escapeHtml(p.name)}${p.unit ? " (" + escapeHtml(p.unit) + ")" : ""}</option>`
  ).join("");

  const tr = document.createElement("tr");
  tr.id = rowId;
  tr.innerHTML = `
    <td><select class="q-line-product">
      <option value="">Choose a product…</option>
      ${options}
    </select></td>
    <td><input type="number" class="q-line-qty" value="1" min="0" step="0.01" /></td>
    <td class="line-price">— ฿</td>
    <td style="text-align:center"><input type="checkbox" class="q-line-taxed" checked /></td>
    <td class="line-amount">0 ฿</td>
    <td><button type="button" class="btn-icon remove-line-btn" title="Remove line">×</button></td>
  `;
  quoteLinesBody.appendChild(tr);

  tr.querySelector(".q-line-product").addEventListener("change", () => recomputeQuoteTotals());
  tr.querySelector(".q-line-qty").addEventListener("input", () => recomputeQuoteTotals());
  tr.querySelector(".q-line-taxed").addEventListener("change", () => recomputeQuoteTotals());
  tr.querySelector(".remove-line-btn").addEventListener("click", () => {
    tr.remove();
    recomputeQuoteTotals();
  });

  recomputeQuoteTotals();
}

function collectQuoteLines() {
  return Array.from(quoteLinesBody.querySelectorAll("tr")).map(tr => {
    const select = tr.querySelector(".q-line-product");
    const option = select.selectedOptions[0];
    const productId = select.value || null;
    const unitPrice = option && option.dataset.price ? Number(option.dataset.price) : 0;
    const quantity = Number(tr.querySelector(".q-line-qty").value) || 0;
    const taxed = tr.querySelector(".q-line-taxed").checked;
    const description = productId ? option.textContent : "";
    const amount = Math.round(unitPrice * quantity * 100) / 100;

    tr.querySelector(".line-price").textContent = productId ? `${unitPrice.toLocaleString()} ฿` : "— ฿";
    tr.querySelector(".line-amount").textContent = `${amount.toLocaleString()} ฿`;

    return { productId, description, unitPrice, quantity, taxed, amount };
  }).filter(line => line.productId && line.quantity > 0);
}

function recomputeQuoteTotals() {
  const lines = collectQuoteLines();
  const subtotal = lines.reduce((sum, l) => sum + l.amount, 0);
  const taxableAmount = lines.filter(l => l.taxed).reduce((sum, l) => sum + l.amount, 0);
  const taxRate = Number(document.getElementById("q-tax-rate").value) || 0;
  const otherCharge = Number(document.getElementById("q-other").value) || 0;
  const taxDue = Math.round(taxableAmount * (taxRate / 100) * 100) / 100;
  const total = Math.round((subtotal + taxDue + otherCharge) * 100) / 100;

  document.getElementById("q-subtotal").textContent = `${subtotal.toLocaleString()} ฿`;
  document.getElementById("q-taxable").textContent = `${taxableAmount.toLocaleString()} ฿`;
  document.getElementById("q-tax-due").textContent = `${taxDue.toLocaleString()} ฿`;
  document.getElementById("q-total").textContent = `${total.toLocaleString()} ฿`;

  return { lines, subtotal, taxableAmount, taxRate, taxDue, otherCharge, total };
}

document.getElementById("q-tax-rate").addEventListener("input", recomputeQuoteTotals);
document.getElementById("q-other").addEventListener("input", recomputeQuoteTotals);

quoteForm.addEventListener("submit", async (e) => {
  e.preventDefault();
  quoteError.textContent = "";

  const entity = document.getElementById("q-entity").value;
  const validUntil = document.getElementById("q-valid-until").value;
  const { lines, subtotal, taxableAmount, taxRate, taxDue, otherCharge, total } = recomputeQuoteTotals();

  if (!lines.length) {
    quoteError.textContent = "Add at least one product with a quantity greater than zero.";
    return;
  }
  if (!validUntil) {
    quoteError.textContent = "Set a valid-until date.";
    return;
  }

  const submitBtn = document.getElementById("generate-pdf-btn");
  submitBtn.disabled = true;
  submitBtn.textContent = "Generating…";

  try {
    const { data: quoteNumber, error: numError } = await sb.rpc("next_quote_number", { p_entity: entity });
    if (numError) throw numError;

    const customer = {
      name: document.getElementById("q-cust-name").value.trim(),
      company: document.getElementById("q-cust-company").value.trim(),
      address: document.getElementById("q-cust-address").value.trim(),
      cityZip: document.getElementById("q-cust-cityzip").value.trim(),
      phone: document.getElementById("q-cust-phone").value.trim(),
    };

    const { data: savedQuote, error: qError } = await sb.from("quotations").insert({
      quote_number: quoteNumber,
      client_id: currentQuoteClient.id,
      created_by: myProfile.id,
      entity,
      customer_name: customer.name || null,
      customer_company: customer.company || null,
      customer_address: customer.address || null,
      customer_city_zip: customer.cityZip || null,
      customer_phone: customer.phone || null,
      valid_until: validUntil,
      tax_rate: taxRate,
      other_charge: otherCharge,
      subtotal, taxable_amount: taxableAmount, tax_due: taxDue, total,
    }).select().single();
    if (qError) throw qError;

    const { error: linesError } = await sb.from("quotation_lines").insert(
      lines.map(l => ({
        quotation_id: savedQuote.id,
        product_id: l.productId,
        description: l.description,
        unit_price: l.unitPrice,
        quantity: l.quantity,
        taxed: l.taxed,
        amount: l.amount,
      }))
    );
    if (linesError) throw linesError;

    generateQuotePDF({ quoteNumber, entity, customer, validUntil, lines, subtotal, taxableAmount, taxRate, taxDue, otherCharge, total });

    // Best-effort notification — a failure here should never block the rep
    // from having already gotten their PDF and saved record.
    if (typeof emailjs !== "undefined" && EMAILJS_SERVICE_ID && EMAILJS_TEMPLATE_ID) {
      emailjs.send(EMAILJS_SERVICE_ID, EMAILJS_TEMPLATE_ID, {
        quote_number: quoteNumber,
        entity,
        customer_name: customer.name,
        customer_company: customer.company,
        total: `${total.toLocaleString()} ฿`,
        valid_until: validUntil,
        rep_name: myProfile.full_name,
        client_name: currentQuoteClient.name,
      }).catch(err => console.warn("Quotation email notification failed:", err));
    }

    closeQuoteModal();
  } catch (err) {
    quoteError.textContent = "Couldn't generate quotation: " + (err.message || err);
  } finally {
    submitBtn.disabled = false;
    submitBtn.textContent = "Generate PDF";
  }
});

// ---------------------------------------------------------------- PDF layout
// Mirrors the existing Excel quotation template field-for-field (company
// block + logo top-left, QUOTATION/date/quote#/valid-until top-right,
// CUSTOMER block, line-item table, Terms & Conditions + signature line on
// the left, Subtotal/Taxable/Tax rate/Tax due/Other/TOTAL on the right,
// thank-you footer) so it looks like the document your clients already know,
// not a new unfamiliar one.
const ENTITY_ADDRESS = ["258/20 RAMA III SOI 12", "BANG KHO LEM", "BANGKOK 10120"];

function generateQuotePDF(q) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: "pt", format: "a4" });
  const pageWidth = doc.internal.pageSize.getWidth();
  const marginX = 40;
  const rightX = pageWidth - marginX;

  doc.addImage(LOGO_BASE64, "PNG", marginX, 30, 60, 60);

  doc.setFont(undefined, "bold");
  doc.setFontSize(14);
  doc.text(q.entity.toUpperCase(), marginX + 70, 48);
  doc.setFont(undefined, "normal");
  doc.setFontSize(9);
  ENTITY_ADDRESS.forEach((line, i) => doc.text(line, marginX + 70, 62 + i * 12));

  doc.setFont(undefined, "bold");
  doc.setFontSize(18);
  doc.text("QUOTATION", rightX, 45, { align: "right" });
  doc.setFont(undefined, "normal");
  doc.setFontSize(9);
  const headerRows = [
    ["DATE", new Date().toLocaleDateString("en-GB")],
    ["QUOTE", q.quoteNumber],
    ["VALID UNTIL", new Date(q.validUntil).toLocaleDateString("en-GB")],
  ];
  headerRows.forEach((row, i) => {
    const y = 62 + i * 13;
    doc.text(row[0], rightX - 140, y);
    doc.text(String(row[1]), rightX, y, { align: "right" });
  });

  let y = 120;
  doc.setFont(undefined, "bold");
  doc.setFontSize(10);
  doc.text("CUSTOMER", marginX, y);
  doc.setFont(undefined, "normal");
  y += 14;
  const custLines = [
    q.customer.name && `Name: ${q.customer.name}`,
    q.customer.company && `Company: ${q.customer.company}`,
    q.customer.address && `Address: ${q.customer.address}`,
    q.customer.cityZip && `City/ZIP: ${q.customer.cityZip}`,
    q.customer.phone && `Phone: ${q.customer.phone}`,
  ].filter(Boolean);
  custLines.forEach(line => { doc.text(line, marginX, y); y += 13; });

  const tableStartY = Math.max(y + 12, 170);
  doc.autoTable({
    startY: tableStartY,
    margin: { left: marginX, right: marginX },
    head: [["DESCRIPTION", "UNIT PRICE", "QUANTITY", "TAXED", "AMOUNT"]],
    body: q.lines.map(l => [
      l.description,
      `${l.unitPrice.toLocaleString()} ฿`,
      String(l.quantity),
      l.taxed ? "Yes" : "No",
      `${l.amount.toLocaleString()} ฿`,
    ]),
    styles: { fontSize: 9, cellPadding: 5 },
    headStyles: { fillColor: [47, 111, 79], textColor: 255 },
    columnStyles: { 1: { halign: "right" }, 2: { halign: "right" }, 3: { halign: "center" }, 4: { halign: "right" } },
  });

  const afterTableY = doc.lastAutoTable.finalY + 20;

  // Totals block, right-aligned, mirrors the template's Subtotal/Taxable/
  // Tax rate/Tax due/Other/TOTAL stack.
  const totalsRows = [
    ["Subtotal", q.subtotal],
    ["Taxable", q.taxableAmount],
    ["Tax rate", `${q.taxRate}%`],
    ["Tax due", q.taxDue],
    ["Other", q.otherCharge],
  ];
  let ty = afterTableY;
  doc.setFontSize(9);
  totalsRows.forEach(([label, value]) => {
    doc.text(label, rightX - 140, ty);
    doc.text(typeof value === "number" ? `${value.toLocaleString()} ฿` : String(value), rightX, ty, { align: "right" });
    ty += 14;
  });
  doc.setFont(undefined, "bold");
  doc.setFontSize(11);
  doc.text("TOTAL", rightX - 140, ty + 4);
  doc.text(`${q.total.toLocaleString()} ฿`, rightX, ty + 4, { align: "right" });
  doc.setFont(undefined, "normal");

  // Terms & Conditions + signature line, left column, same boilerplate text
  // as the Excel template.
  let termsY = afterTableY;
  doc.setFont(undefined, "bold");
  doc.setFontSize(10);
  doc.text("Terms & Conditions", marginX, termsY);
  doc.setFont(undefined, "normal");
  doc.setFontSize(9);
  const terms = [
    "1. Customer will be billed after indicating acceptance of this quote",
    "2. Payment will be due prior to delivery of service and goods",
    "3. Please email the signed price quote to the address above",
  ];
  termsY += 16;
  terms.forEach(line => {
    const wrapped = doc.splitTextToSize(line, rightX - 160 - marginX);
    doc.text(wrapped, marginX, termsY);
    termsY += 12 * wrapped.length;
  });

  termsY += 14;
  doc.text("Customer acceptance (sign below)", marginX, termsY);
  termsY += 26;
  doc.text("x ____________________________", marginX, termsY);
  termsY += 14;
  doc.setFontSize(8);
  doc.text("Print Name", marginX, termsY);

  const footerY = Math.max(ty + 40, termsY + 30);
  doc.setFontSize(9);
  doc.text(
    doc.splitTextToSize(
      "Please do not hesitate to contact us if you have any questions. We would be pleased to assist you. Thank you for your business.",
      pageWidth - marginX * 2
    ),
    marginX, Math.min(footerY, doc.internal.pageSize.getHeight() - 40)
  );

  doc.save(`${q.quoteNumber}.pdf`);
}
